code.C:
#include <stdio.h>

int main() {
    int y;
    if (scanf("%d", &y) == 1) {
        if ((y % 400 == 0) || (y % 4 == 0 && y % 100 != 0)) {
            printf("Leap Year\n");
        } else {
            printf("Not a Leap Year\n");
        }
    }
    return 0;
}

