code.Java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int y = sc.nextInt();
            boolean isLeap = (y % 400 == 0) || (y % 4 == 0 && y % 100 != 0);
            System.out.println(isLeap ? "Leap Year" : "Not a Leap Year");
        }
    }
}

